type Cache {
  order: List[Str],
  vals: Map[Str, Str],
}

fn touch(order: List[Str], key: Str) -> List[Str] {
  return order.filter(fn(x) => x != key).push(key)
}

fn put_key(c: Cache, capacity: Int, key: Str, value: Str) -> Cache {
  if capacity == 0 {
    return c
  }
  if c.vals.has(key) {
    return Cache { order: touch(c.order, key), vals: c.vals.set(key, value) }
  }
  var order: List[Str] = c.order
  var vals: Map[Str, Str] = c.vals
  if order.len() >= capacity {
    let oldest = order.get_or(0, "")
    order = order.drop(1)
    vals = vals.remove(oldest)
  }
  return Cache { order: order.push(key), vals: vals.set(key, value) }
}

pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  let empty_order: List[Str] = []
  let empty_vals: Map[Str, Str] = Map {}
  var cache: Cache = Cache { order: empty_order, vals: empty_vals }
  var out: List[Str] = []
  for op in ops {
    let parts = op.split(" ")
    let kind = parts.get_or(0, "")
    let key = parts.get_or(1, "")
    if kind == "put" {
      cache = put_key(cache, capacity, key, parts.drop(2).join(" "))
    } else {
      match cache.vals.get(key) {
        Some(v) => {
          out = out.push(v)
          cache = Cache { order: touch(cache.order, key), vals: cache.vals }
        },
        None => {
          out = out.push("-")
        },
      }
    }
  }
  return out
}
